function timingSafeEq(a,b){if(a.length!==b.length)return false;let x=0;for(let i=0;i<a.length;i++)x|=a.charCodeAt(i)^b.charCodeAt(i);return x===0}
async function verifyAccess(req){const token=req.headers.get('x-nepal-miti-access')||'';const parts=token.split('.');if(parts.length!==2)return false;const exp=Number(parts[0]);if(!Number.isFinite(exp)||exp<Date.now()||exp>Date.now()+3*3600000)return false;const iphash=(await digestText(clientIp(req)+'|nepal-miti-access')).slice(0,32);const expected=await hmacHex(String(exp)+'|'+iphash);return timingSafeEq(expected,parts[1])}

